        # find start codons and extend
        while i < L-3:
            if s[i:i+3]=="ATG":
                j=i
                while j < L-3:
                    cod=s[j:j+3]
                    if cod in stops:
                        break
                    j+=3
                aa=(j-i)//3
                if aa>=minaa:
                    orfs.append((i,j,aa,'+'))
                i+=3
            else:
                i+=3
    return orfs

