    lines = f.read().splitlines()
seq = "".join(l.strip() for l in lines[1:] if not l.startswith(">"))
n = len(seq)
comp = {'A':'T','T':'A','G':'C','C':'G','N':'N'}
def rc(s):
    return "".join(comp[b] for b in reversed(s))

stops = {"TAA","TAG","TGA"}

def longest_orfs(s, strand, minaa=60):
    L=len(s)
    res=[]
    for frame in range(3):
        # build translation of this frame, split by stops
        # start positions of ATG
        positions=[i for i in range(frame, L-2, 3) if s[i:i+3]=="ATG"]
        # for each ATG find next in-frame stop
        for a in positions:
            j=a
            while j < L-2 and s[j:j+3] not in stops:
                j+=3
            aa=(j-a)//3
            if aa>=minaa:
                res.append((a,j,aa))
    # sort by length desc
    res.sort(key=lambda x:-x[2])
    out=[]
    for a,j,aa in res:
        if strand=="+":
            out.append((a+1, j, aa, '+'))
        else:
            out.append((n-j, n-a, aa, '-'))
    return out

print("Minus strand ORFs (top):")
for coord in longest_orfs(rc(seq), '-', 60)[:12]:
    print(coord)
print()
print("Plus strand ORFs (top):")
for coord in longest_orfs(seq, '+', 60)[:12]:
    print(coord)
