with open("region.fasta") as f:
    lines = f.read().splitlines()
seq = "".join(l.strip() for l in lines[1:] if not l.startswith(">"))
n = len(seq)
comp = {'A':'T','T':'A','G':'C','C':'G','N':'N'}
def rc(s):
    return "".join(comp[b] for b in reversed(s))

def ir_search(seq, L, maxmis):
    d={}
    for i in range(n-L+1):
        d.setdefault(seq[i:i+L],[]).append(i)
    found=[]
    for i in range(n-L+1):
        w=seq[i:i+L]
        r=rc(w)
        # allow mismatches: try all words in dict that are within maxmis of r
        for word,poses in d.items():
            mm=sum(1 for a,b in zip(word,r) if a!=b)
            if mm<=maxmis:
                for j in poses:
                    if j>i:
                        found.append((mm,L,i,j,w,word))
    # dedupe, keep best
    found.sort()
    return found

seen=set()
print("Imperfect inverted repeats:")
res=[]
for L in [16,18,20,22,24,26,30,34,40]:
    maxmis = max(2, int(L*0.15))
    for mm,L2,i,j,w,word in ir_search(seq,L,maxmis):
        key=(i,j,L)
        if key in seen: continue
        seen.add(key)
        res.append((mm,L,i,j,w,word))
res.sort()
for mm,L,i,j,w,word in res[:25]:
    print(f"  L={L} mm={mm} fwd {i+1}-{i+L} rev {j+1}-{j+L}  {w} / {word}")
"}

