with open("region.fasta") as f:
    lines = f.read().splitlines()
seq = "".join(l.strip() for l in lines[1:] if not l.startswith(">"))
n=len(seq)
comp = {'A':'T','T':'A','G':'C','C':'G','N':'N'}
def rc(s):
    return "".join(comp[b] for b in reversed(s))

def extend_direct(i,j):
    # seq[i..] vs seq[j..], extend with mismatches allowed
    L=0; mm=0
    while i+L<n and j+L<n:
        if seq[i+L]==seq[j+L]:
            L+=1
        else:
            mm+=1
            if mm> max(2,L//10): break
            L+=1
    return L, mm
def extend_inv(i,j):
    # seq[i..] vs rc of seq[j..]? Actually seq[i:i+L] should equal rc(seq[j:j+L])
    L=0; mm=0
    while i+L<n and j-L>=0:
        if seq[i+L]==comp[seq[j-L]]:
            L+=1
        else:
            mm+=1
            if mm>max(2,L//10): break
            L+=1
    return L, mm

k=15
seeds={}
for i in range(n-k+1):
    seeds.setdefault(seq[i:i+k],[]).append(i)

direct_hits=[]
inv_hits=[]
for i in range(n-k+1):
    w=seq[i:i+k]
    for j in seeds.get(w,[]):
        if j>=i+k:
            L,mm=extend_direct(i,j)
            direct_hits.append((L,mm,i,j))
    r=rc(w)
    for j in seeds.get(r,[]):
        if j>=i+k:
            L,mm=extend_inv(i,j)  # careful: this uses seed as inverted
            inv_hits.append((L,mm,i,j))

direct_hits.sort(reverse=True)
inv_hits.sort(reverse=True)
print("Top DIRECT repeat pairs (L, mismatches, i, j) 1-based:")
for L,mm,i,j in direct_hits[:12]:
    print(f"  L={L} mm={mm} {i+1}..{i+L}  vs  {j+1}..{j+L}")
print()
print("Top INVERTED repeat pairs:")
for L,mm,i,j in inv_hits[:12]:
    print(f"  L={L} mm={mm} left {i+1}..{i+L}  vsrc {j+1}..{j+L}")
"}
